#!/usr/bin/env tsx

import { spawn } from 'node:child_process';
import * as fs from 'node:fs';
import * as os from 'node:os';
import * as path from 'node:path';

import { extractGlobalRtwsChdir } from '../main/bootstrap/rtws-cli';

function printHelp(): void {
  console.log(`
Dominds Tests CLI

Usage:
  pnpm -C tests run rtws -- [--shared-rtws] [-C <dir>] <script.ts> [script args...]

Notes:
  - Default mode is isolated: each run copies tests/script-rtws into a unique temp rtws.
  - This avoids cross-test pollution and allows safe parallel runs.
  - Use --shared-rtws only for debugging (runs directly in tests/script-rtws).
  - -C is parsed for parity with dominds CLI, but only tests/script-rtws is accepted after path resolution.
  - Failed isolated runs keep their workspace for investigation.
  - Set DOMINDS_TEST_RTWS_KEEP_TMP=1 to also keep successful isolated runs.

	  Examples:
	  pnpm -C tests run rtws -- kernel-driver/runtime-reminder-context.ts
	  pnpm -C tests run rtws -- --shared-rtws kernel-driver/sideDialog-queue-commit-mirror.ts
	`);
}

type RtwsMode = 'isolated' | 'shared';

type ModeParseResult = Readonly<{
  mode: RtwsMode;
  argv: ReadonlyArray<string>;
}>;

function parseRtwsMode(rawArgv: ReadonlyArray<string>): ModeParseResult {
  const envModeRaw = process.env.DOMINDS_TEST_RTWS_MODE?.trim().toLowerCase();
  let mode: RtwsMode = envModeRaw === 'shared' ? 'shared' : 'isolated';
  const args: string[] = [];
  for (const arg of rawArgv) {
    if (arg === '--shared-rtws') {
      mode = 'shared';
      continue;
    }
    if (arg === '--isolated-rtws') {
      mode = 'isolated';
      continue;
    }
    args.push(arg);
  }
  return { mode, argv: args };
}

async function main(): Promise<void> {
  const testsRoot = path.resolve(__dirname);
  const templateRtws = path.resolve(testsRoot, 'script-rtws');
  const rawArgv = process.argv.slice(2);
  const normalizedArgv = rawArgv.length > 0 && rawArgv[0] === '--' ? rawArgv.slice(1) : rawArgv;
  const { mode, argv: argvForParse } = parseRtwsMode(normalizedArgv);

  let parsed: { chdir?: string; argv: ReadonlyArray<string> };
  try {
    parsed = extractGlobalRtwsChdir({ argv: argvForParse });
  } catch (err) {
    console.error('Error:', err instanceof Error ? err.message : String(err));
    process.exit(1);
    return;
  }

  const args = parsed.argv;
  if (args.length === 0 || args[0] === '-h' || args[0] === '--help' || args[0] === 'help') {
    printHelp();
    process.exit(0);
    return;
  }

  if (!fs.existsSync(templateRtws)) {
    console.error(`Error: required rtws template not found: ${templateRtws}`);
    process.exit(1);
    return;
  }

  if (parsed.chdir && path.resolve(parsed.chdir) !== templateRtws) {
    console.error(
      `Error: only tests/script-rtws is allowed for script tests. Requested: ${parsed.chdir}`,
    );
    process.exit(1);
    return;
  }

  const [scriptRelOrAbs, ...scriptArgs] = args;
  const scriptAbs = path.isAbsolute(scriptRelOrAbs)
    ? scriptRelOrAbs
    : path.resolve(testsRoot, scriptRelOrAbs);

  if (!fs.existsSync(scriptAbs)) {
    console.error(`Error: script not found: ${scriptAbs}`);
    process.exit(1);
    return;
  }

  let runRtws = templateRtws;
  let tempRoot: string | null = null;
  if (mode === 'isolated') {
    try {
      tempRoot = fs.mkdtempSync(path.join(os.tmpdir(), 'dominds-tests-rtws-'));
      runRtws = path.join(tempRoot, 'rtws');
      fs.cpSync(templateRtws, runRtws, { recursive: true });
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err);
      console.error(`Error: failed to prepare isolated rtws: ${message}`);
      process.exit(1);
      return;
    }
  } else {
    console.warn('[tests/cli] Using shared tests/script-rtws (--shared-rtws).');
  }

  const child = spawn(
    process.execPath,
    [
      require.resolve('tsx/cli'),
      '--tsconfig',
      path.resolve(testsRoot, 'tsconfig.json'),
      path.resolve(testsRoot, 'rtws-script-runner.ts'),
      scriptAbs,
      ...scriptArgs,
    ],
    {
      cwd: runRtws,
      stdio: 'inherit',
      env: {
        ...process.env,
        DOMINDS_TEST_RTWS_MANAGED: '1',
        DOMINDS_TEST_RTWS_MODE: mode,
        DOMINDS_TEST_RTWS_TEMPLATE: templateRtws,
      },
    },
  );

  const cleanupTempRtws = (preserveFailure: boolean): boolean => {
    if (mode !== 'isolated') return true;
    if (!tempRoot) return true;
    if (preserveFailure || process.env.DOMINDS_TEST_RTWS_KEEP_TMP === '1') {
      console.error(`[tests/cli] Keeping isolated rtws at ${tempRoot}`);
      return true;
    }
    try {
      fs.rmSync(tempRoot, { recursive: true, force: true });
      return true;
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err);
      console.error(`Error: failed to cleanup isolated rtws ${tempRoot}: ${message}`);
      return false;
    }
  };

  child.on('error', (err) => {
    console.error(`Test runner failed to start: ${err.message}`);
    const cleaned = cleanupTempRtws(true);
    process.exit(cleaned ? 1 : 2);
  });

  child.on('exit', (code, signal) => {
    let finalExitCode = code ?? 1;
    if (signal) {
      console.error(`Test runner terminated by signal: ${signal}`);
      finalExitCode = 1;
    }

    const cleaned = cleanupTempRtws(finalExitCode !== 0);
    if (!cleaned && finalExitCode === 0) {
      finalExitCode = 1;
    }

    process.exit(finalExitCode);
  });
}

void main().catch((err: unknown) => {
  const message = err instanceof Error ? err.message : String(err);
  console.error(`tests cli failed: ${message}`);
  process.exit(1);
});

#!/usr/bin/env tsx

import { pathToFileURL } from 'node:url';

import {
  clearInstalledGlobalDialogEventBroadcaster,
  installRecordingGlobalDialogEventBroadcaster,
} from '../main/bootstrap/global-dialog-event-broadcaster';

async function main(): Promise<void> {
  const [scriptAbs, ...scriptArgs] = process.argv.slice(2);
  if (!scriptAbs) {
    throw new Error('tests rtws runner requires a target script path');
  }

  process.argv = [process.argv[0] ?? 'node', scriptAbs, ...scriptArgs];
  installRecordingGlobalDialogEventBroadcaster({
    label: 'tests-rtws-runner',
  });
  process.on('exit', () => {
    clearInstalledGlobalDialogEventBroadcaster();
  });

  await import(pathToFileURL(scriptAbs).href);
}

void main().catch((err: unknown) => {
  const message = err instanceof Error ? (err.stack ?? err.message) : String(err);
  console.error(`tests rtws runner failed:\n${message}`);
  process.exit(1);
});

import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { once } from 'node:events';
import fs from 'node:fs/promises';
import http from 'node:http';
import os from 'node:os';
import path from 'node:path';
import YAML from 'yaml';
import { semanticEvidenceCollector } from '../helpers/semantic-evidence';
import { withTempRtws } from '../kernel-driver/helpers';

type Call = { id: string; name: string; args: Record<string, unknown> };
type Wire = { text?: string; calls?: Call[]; thinking?: boolean; invalidSse?: boolean };
function record(value: unknown): value is Record<string, unknown> {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}
function jsonLines(text: string): Record<string, unknown>[] {
  return text.split('\n').flatMap((line) => {
    try {
      const value: unknown = JSON.parse(line);
      return record(value) ? [value] : [];
    } catch {
      return [];
    }
  });
}
function completion(model: string, supplied: Wire) {
  const calls = supplied.calls?.map((call) => ({
    id: call.id,
    type: 'function',
    function: { name: call.name, arguments: JSON.stringify(call.args) },
  }));
  return {
    id: 'given-wire-completion',
    object: 'chat.completion',
    created: 1,
    model,
    choices: [
      {
        index: 0,
        finish_reason: calls?.length ? 'tool_calls' : 'stop',
        message: {
          role: 'assistant',
          content: supplied.text ?? 'given-saying-data:1d37',
          ...(supplied.thinking !== false ? { reasoning_content: 'given-thinking-data:65b2' } : {}),
          ...(calls ? { tool_calls: calls } : {}),
        },
      },
    ],
    usage: { prompt_tokens: 1, completion_tokens: 2, total_tokens: 3 },
  };
}
async function main() {
  const evidence = semanticEvidenceCollector('dominds-live-probe-controls-');
  let recorded = false;
  try {
    await withTempRtws(async (rtws) => {
      // Nested tsx runners bind Unix sockets; keep their owned physical prefix short.
      const artifacts = await fs.mkdtemp(
        path.join(process.platform === 'win32' ? os.tmpdir() : '/tmp', 'lp-'),
      );
      console.log('Owned live-probe control artifacts: ' + artifacts);
      let completed = false;
      let plan: Wire[] = [];
      let requests: Record<string, unknown>[] = [];
      const peerErrors: unknown[] = [];
      const server = http.createServer((request, reply) => {
        const chunks: Buffer[] = [];
        request.on('data', (chunk: Buffer) => chunks.push(chunk));
        request.on('error', (error) => {
          peerErrors.push(error);
          reply.destroy(error);
        });
        request.on('end', () => {
          try {
            const body: unknown = JSON.parse(Buffer.concat(chunks).toString('utf8'));
            assert.ok(record(body));
            assert.equal(request.method, 'POST');
            assert.equal(request.url, '/v1/chat/completions');
            assert.equal(request.headers.authorization === 'Bearer given-local-probe-key', true);
            const response = plan[requests.length];
            requests.push(body);
            console.log(JSON.stringify({ control: 'peer-request', index: requests.length, body }));
            assert.ok(response, 'No unspecified request may be hidden by the controlled peer');
            assert.ok(body.model === 'given-primary' || body.model === 'given-secondary');
            if (body.stream === true) {
              reply.setHeader('content-type', 'text/event-stream');
              if (response.invalidSse) {
                reply.end('data: }\n\ndata: [DONE]\n\n');
                return;
              }
              const base = completion(String(body.model), response);
              const message = base.choices[0]!.message;
              const delta = {
                ...message,
                ...(message.tool_calls
                  ? { tool_calls: message.tool_calls.map((call, index) => ({ index, ...call })) }
                  : {}),
              };
              const chunk = {
                id: base.id,
                object: 'chat.completion.chunk',
                created: 1,
                model: body.model,
                choices: [{ index: 0, delta, finish_reason: null }],
              };
              const finish = {
                ...chunk,
                choices: [{ index: 0, delta: {}, finish_reason: base.choices[0]!.finish_reason }],
                usage: base.usage,
              };
              reply.end(
                'data: ' +
                  JSON.stringify(chunk) +
                  '\n\ndata: ' +
                  JSON.stringify(finish) +
                  '\n\ndata: [DONE]\n\n',
              );
            } else {
              reply.setHeader('content-type', 'application/json');
              reply.end(JSON.stringify(completion(String(body.model), response)));
            }
          } catch (error: unknown) {
            peerErrors.push(error);
            reply.writeHead(500, { 'content-type': 'application/json' });
            reply.end('{"error":{"message":"Controlled peer request fixture failed"}}');
          }
        });
      });
      const listening = once(server, 'listening');
      server.listen(0, '127.0.0.1');
      await listening;
      const address = server.address();
      assert.ok(address && typeof address === 'object');
      const llmYaml = YAML.stringify({
        providers: {
