        );
        let stdout = '',
          stderr = '';
        child.stdout.on('data', (data: Buffer) => {
          stdout += data.toString('utf8');
        });
        child.stderr.on('data', (data: Buffer) => {
          stderr += data.toString('utf8');
        });
        const [code, signal] = await once(child, 'close');
        const rows = jsonLines(stdout);
        await fs.writeFile(
